section.sourcecode:
EnhancedJWTClaimConstraints-2021 { iso(1) identified-organization(3) dod(6) internet(1) security(5) mechanisms(5) pkix(7) id-mod(0) id-mod-eJWTClaimConstraints-2021(101) }
DEFINITIONS EXPLICIT TAGS ::= BEGIN
IMPORTS
id-pe FROM PKIX1Explicit-2009 -- RFC 5912から { iso(1) identified-organization(3) dod(6) internet(1) security(5) mechanisms(5) pkix(7) id-mod(0) id-mod-pkix1-explicit-02(51) }
EXTENSION FROM PKIX-CommonTypes-2009 -- RFC 5912から { iso(1) identified-organization(3) dod(6) internet(1) security(5) mechanisms(5) pkix(7) id-mod(0) id-mod-pkixCommon-02(57) } ;
-- 拡張JWTクレーム制約証明書拡張
ext-eJWTClaimConstraints EXTENSION ::= { SYNTAX EnhancedJWTClaimConstraints IDENTIFIED BY id-pe-eJWTClaimConstraints }
id-pe-eJWTClaimConstraints OBJECT IDENTIFIER ::= { id-pe 33 }
EnhancedJWTClaimConstraints ::= SEQUENCE { mustInclude [0] JWTClaimNames OPTIONAL, -- 列挙されたクレーム名は、iat、orig、destに加えてPASSporTに -- 含まれなければなりません（MUST）。存在しない場合、iat、orig、 -- destがPASSporTに含まれなければなりません（MUST）。 permittedValues [1] JWTClaimValuesList OPTIONAL, -- クレーム名が存在する場合、そのクレームは列挙された値の -- いずれかを含まなければなりません（MUST）。 mustExclude [2] JWTClaimNames OPTIONAL } -- 列挙されたクレーム名は、PASSporTに含まれてはなりません -- （MUST NOT）。 ( WITH COMPONENTS { ..., mustInclude PRESENT } | WITH COMPONENTS { ..., permittedValues PRESENT } | WITH COMPONENTS { ..., mustExclude PRESENT } )
JWTClaimValuesList ::= SEQUENCE SIZE (1..MAX) OF JWTClaimValues
JWTClaimValues ::= SEQUENCE { claim JWTClaimName, values SEQUENCE SIZE (1..MAX) OF UTF8String }
JWTClaimNames ::= SEQUENCE SIZE (1..MAX) OF JWTClaimName
JWTClaimName ::= IA5String
END
